        uint b0 = address(this).balance;
        // fresh contract: pot == 0, so play() with 10 wei cannot revert
        c.play{value: amount}();
        // pot before second play is 0 or 10; in both cases the second 10-wei
        // play also cannot revert (pot is incremented before any transfer)
        c.play{value: amount}();
        uint callerDelta = address(this).balance;
        uint contractBal = address(c).balance;
        // Conservation: caller paid 2*amount total. All of it is either still
        // in the contract, paid back to the caller as winnings, or paid out
        // as at most one 1-wei fee to the bank per play (at most 2 fees).
        // Hence: (caller loss) + contract balance == 20 - fees, fees in [0,2].
        assert(callerDelta + contractBal <= b0 && callerDelta + contractBal >= b0 - 2);
    }
    receive() external payable {}
}

